_prepareItems(aItipItem, aFromAttendee) {
  const item = aItipItem.getItemList()[0];

  // Get ourselves some default text - when we handle organizer properly
  // We'll need a way to configure the Common Name attribute and we should
  // use it here rather than the email address

  const summary = item.getProperty("SUMMARY") || "";
  let subject = "";
  let body = "";
  switch (aItipItem.responseMethod) {
    case "REQUEST": {
      const usePrefixes = Services.prefs.getBoolPref(
        "calendar.itip.useInvitationSubjectPrefixes",
        true
      );
      if (usePrefixes) {
        const seq = item.getProperty("SEQUENCE");
        const subjectId =
          seq && seq > 0 ? "itip-request-updated-subject" : "itip-request-subject";
        subject = lazy.l10n.formatValueSync(subjectId, { summary });
      } else {
        subject = summary;
      }
      body = lazy.l10n.formatValueSync("itip-request-body", {
        organizer: item.organizer ? item.organizer.toString() : "",
        summary,
      });
      break;
    }
    case "CANCEL": {
      subject = lazy.l10n.formatValueSync("itip-cancel-subject", { summary });
      body = lazy.l10n.formatValueSync("itip-cancel-body", {
        organizer: item.organizer ? item.organizer.toString() : "",
        summary,
      });
      break;
    }
    case "DECLINECOUNTER": {
      subject = lazy.l10n.formatValueSync("itip-decline-counter-subject", { summary });
      body = lazy.l10n.formatValueSync("itip-decline-counter-body", {
        organizer: item.organizer ? item.organizer.toString() : "",
        summary,
      });
      break;
    }
    case "REPLY": {
      // Get my participation status
      if (!aFromAttendee && aItipItem.identity) {
        aFromAttendee = item.getAttendeeById(cal.email.prependMailTo(aItipItem.identity));
      }
      if (!aFromAttendee) {
        // should not happen anymore
        return false;
      }

      // work around BUG 351589, the below just removes RSVP:
      aItipItem.setAttendeeStatus(aFromAttendee.id, aFromAttendee.participationStatus);
      const myPartStat = aFromAttendee.participationStatus;
      const name = aFromAttendee.toString();

      // Generate proper body from my participation status
      let subjectId, bodyId;
      switch (myPartStat) {
        case "ACCEPTED":
          subjectId = "itip-reply-subject-accept";
          bodyId = "itip-reply-body-accept";
          break;
        case "TENTATIVE":
          subjectId = "itip-reply-subject-tentative";
          bodyId = "itip-reply-body-accept";
          break;
        case "DECLINED":
          subjectId = "itip-reply-subject-decline";
          bodyId = "itip-reply-body-decline";
          break;
        default:
          subjectId = "itip-reply-subject";
          bodyId = "itip-reply-body-accept";
          break;
      }
      subject = lazy.l10n.formatValueSync(subjectId, { summary });
      body = lazy.l10n.formatValueSync(bodyId, { attendee: name });
      break;
    }
  }

  // Retrieve the COMMENT property
  const comment = item.getProperty("COMMENT");

  // Append COMMENT field to the body
  if (comment) {
    body += "\n\n" + lazy.l10n.formatValueSync("imip-html-comment") + "\n" + comment;
  }
